import React, { useEffect, useState } from 'react';
import Lottie from 'lottie-react';
import './FeaturesSection.css';

const features = [
  {
    title: 'AI Map Matching',
    desc: 'Sub-meter accuracy. Snap raw noisy GPS traces directly onto actual road geometry with 97.3%+ accuracy across urban canyons.',
    lottieFile: '/Brain.json',
  },
  {
    title: 'MIMIC Neural Prediction',
    desc: 'Continuous offline tracking. Predict vehicle position during total satellite dropouts in tunnels and mountain passes using on-device neural filtering.',
    lottieFile: '/Multi Cluster.json',
  },
  {
    title: 'Real-Time Telemetry',
    desc: 'Sub-100ms latency pipeline. Scale effortlessly across thousands of concurrent vehicle streams with sub-meter spatial deviation.',
    lottieFile: '/Ticket 1.json',
  },
  {
    title: 'Privacy-First API',
    desc: 'Zero third-party sharing. Drop-in REST API and SDKs for iOS, Android, and Web where all telemetry stays inside your own infrastructure.',
    lottieFile: '/Community.json',
  },
];

const FeatureCard = ({ title, desc, lottieFile }) => {
  const [animationData, setAnimationData] = useState(null);

  useEffect(() => {
    // Fetch the lottie json from public folder
    fetch(process.env.PUBLIC_URL + lottieFile)
      .then((res) => res.json())
      .then((data) => setAnimationData(data))
      .catch((err) => console.error('Error loading lottie:', err));
  }, [lottieFile]);

  return (
    <div className="fs-card">
      <div className="fs-card-icon-slot">
        {animationData ? (
          <Lottie animationData={animationData} loop={true} autoplay={true} className="fs-lottie" />
        ) : (
          <div className="fs-lottie-placeholder" />
        )}
      </div>
      <h3 className="fs-card-title">{title}</h3>
      <p className="fs-card-desc">{desc}</p>
    </div>
  );
};

export const FeaturesSection = () => {
  return (
    <section className="fs-section" aria-labelledby="features-heading">

      <div className="fs-header-wrap">
        <h2 id="features-heading" className="fs-heading">
          Replace fragile GPS estimation<br />
          with a single unified platform for<br />
          <span className="fs-heading-highlight">sub-meter tracking & offline routes.</span>
        </h2>

        <p className="fs-subheading">
          Stop assembling location pipelines piece by piece. Running location intelligence at scale usually means struggling with noisy multipath signals, urban canyons, and satellite dropouts across fragmented SDKs.
        </p>
      </div>

      <div className="fs-cards-grid">
        {features.map((feature, idx) => (
          <FeatureCard 
            key={idx} 
            title={feature.title} 
            desc={feature.desc} 
            lottieFile={feature.lottieFile} 
          />
        ))}
      </div>

    </section>
  );
};
